mapper.select:
SELECT id,order_no,customer_name,customer_phone,status,channel,amount,currency,region,created_at FROM orders
AND EXISTS (SELECT 1 FROM export_task_orders selected WHERE selected.task_id=#{taskId} AND selected.order_id=orders.id) AND NOT EXISTS (SELECT 1 FROM export_task_orders excluded WHERE excluded.task_id=#{taskId} AND excluded.order_id=orders.id) AND (created_at < #{after.createdAt} OR (created_at=#{after.createdAt} AND id<#{after.id}))
ORDER BY created_at DESC,id DESC LIMIT #{limit}
